INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (1, 'snowy-actuator-app-dev.yaml', 'dev', '# 服务配置\nserver:\n  port: 9001\n\n# spring相关配置\nspring:\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"', 'c9ede45bff4951a66e71be96c176b17b', '2024-04-24 14:33:07', '2026-07-20 15:50:39', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (2, 'snowy-sentinel-app-dev.yaml', 'dev', '# 服务配置\nserver:\n  port: 9002\n  servlet:\n    #spring settings\n    encoding:\n      force: true\n      charset: UTF-8\n      enabled: true\n    #cookie name setting\n    session:\n      cookie:\n        name:\n          sentinel_dashboard_cookie: sentinel_dashboard_cookie\n\n# spring相关配置\nspring:\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n# logging settings\nlogging:\n  level:\n    org:\n      springframework:\n        web: INFO\n  file:\n    name: ${user.home}/logs/csp/sentinel-dashboard.log\n  pattern:\n    file: \'%d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\'\n    console: \'%d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\'\n\n# auth settings\nauth:\n  filter:\n    exclude-urls: /,/auth/login,/auth/logout,/registry/machine,/version,/actuator/**,/details\n    exclude-url-suffixes: htm,html,js,css,map,ico,ttf,woff,png\n  # If auth.enabled=false, Sentinel console disable login\n  username: sentinel\n  password: sentinel\n\n# Inject the dashboard version. It\'s required to enable\n# filtering in pom.xml for this resource file.\nsentinel:\n  dashboard:\n    version: 1.8.7', 'de07d06fe46cc30bd86b4c276e20b12c', '2024-04-24 14:33:29', '2026-07-20 15:50:50', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (3, 'snowy-gateway-app-dev.yaml', 'dev', '# 服务配置\nserver:\n  port: 9003\n\n# spring相关配置\nspring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/snowy-cloud?useUnicode=true&characterEncoding=utf-8&useSSL=false&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true&useInformationSchema=true&rewriteBatchedStatements=true\n    username: root\n    password: 123456\n\n  # Oracle数据库\n  #spring:\n  #  datasource:\n  #    driver-class-name: oracle.jdbc.OracleDriver\n  #    url: jdbc:oracle:thin:@localhost:1521:xe\n  #    username: SNOWY-CLOUD-ORACLE\n  #    password: 123456\n\n  # SQLServer配置\n  #spring:\n  #  datasource:\n  #    driverClassName: com.microsoft.sqlserver.jdbc.SQLServerDriver\n  #    url: jdbc:sqlserver://localhost:1433;DatabaseName=snowy-cloud-mssql\n  #    username: sa\n  #    password: 123456\n\n  # PostgreSQL配置\n  #spring:\n  #  datasource:\n  #    driverClassName: org.postgresql.Driver\n  #    url: jdbc:postgresql://127.0.0.1:5432/snowy-cloud-postgresql\n  #    username: postgres\n  #    password: 123456\n\n  # 达梦数据库配置\n  #spring:\n  #  datasource:\n  #    driver-class-name: dm.jdbc.driver.DmDriver\n  #    url: jdbc:dm://localhost:5236/SYSDBA\n  #    username: SYSDBA\n  #    password: 123456789\n\n  # 人大金仓数据库\n  #spring:\n  #  datasource:\n  #    driver-class-name: com.kingbase8.Driver\n  #    url: jdbc:kingbase8://localhost:54321/snowy-cloud-kingbase\n  #    username: system\n  #    password: 123456\n  # #人大金仓数据库兼容问题，不需要加在sql语句中加public的解决方法：\n  # #在根目录data下的kingbase.conf文档里面找到search_path = \'\"$user\",PUBLIC,sys_catalog\'进行替换放开\n  # #重启数据库即可完全兼容，注意 sql中不能出现mysql中的关键字的单引号\n\n  # redis相关配置\n  data:\n    redis:\n      database: 1\n      host: 127.0.0.1\n      port: 6379\n      password:\n      timeout: 10s\n\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n    sentinel:\n      transport:\n        dashboard: localhost:9002\n        port: 8719\n      scg:\n        fallback:\n          mode: response\n          response-status: 455\n          response-body: error!\n    # gateway配置\n    gateway:\n      default-filters:\n        - DedupeResponseHeader=Access-Control-Allow-Origin\n      globalcors:\n        add-to-simple-url-handler-mapping: true\n        corsConfigurations:\n          \'[/**]\':\n            allowed-origins-patterns: \"*\"\n            allowed-methods: \"*\"\n            allowed-headers: \"*\"\n            allow-credentials: true\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        - id: snowy-web-app\n          uri: lb://snowy-web-app\n          predicates:\n            - Path=/api/webapp/**\n          filters:\n            - SwaggerHeaderFilter\n            - StripPrefix=2 #去掉Path中前两个节点\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n        - id: snowy-web-app\n          uri: lb://snowy-web-app\n          predicates:\n            - Path=/druid/**\n          filters:\n            - SwaggerHeaderFilter\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n        - id: snowy-biz-app\n          uri: lb://snowy-biz-app\n          predicates:\n            - Path=/api/bizapp/**\n          filters:\n            - SwaggerHeaderFilter\n            - StripPrefix=2 #去掉Path中前两个节点\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n#########################################\n# sa-token configuration\n#########################################\nsa-token:\n  token-name: token\n  timeout: 2592000\n  active-timeout: -1\n  is-concurrent: true\n  is-share: false\n  max-login-count: -1\n  token-style: random-32\n  is-log: false\n  is-print: false\n\n  # sa-token alone-redis configuration\n  alone-redis:\n    database: ${spring.data.redis.database}\n    host: ${spring.data.redis.host}\n    port: ${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    timeout: ${spring.data.redis.timeout}\n\n  # sso configuration\n  sso-client:\n    client:\n    auth-url:\n    signout-url:\n    push-url:\n    secret-key:\n\n# knife4j 文档聚合\nknife4j:\n  enable: true\n  production: false\n  basic:\n    enable: true\n    username: snowyAdmin\n    password: Snowy@2026!\n  setting:\n    enableOpenApi: false\n    enableSwaggerModels: false\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Apache License 2.0 | Copyright 2022-[SNOWY](https://www.xiaonuo.vip)\n  # gateway聚合swagger文档\n  gateway:\n    enabled: true\n    # 排序规则(tag/operation排序自4.2.0版本新增)\n    # 取值：alpha-默认排序规则，官方swagger-ui默认实现,order-Knife4j提供的增强排序规则，开发者可扩展x-order，根据数值来自定义排序\n    tags-sorter: order\n    operations-sorter: order\n    # 指定手动配置的模式(默认为该模式)\n    strategy: manual\n    routes:\n      - name: SNOWY-PLUGIN-AUTH\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-AUTH\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-BIZ\n        url: /api/bizapp/v3/api-docs/SNOWY-PLUGIN-BIZ\n        service-name: snowy-biz-app\n        context-path: /\n      - name: SNOWY-PLUGIN-CLIENT\n        url: /api/bizapp/v3/api-docs/SNOWY-PLUGIN-CLIENT\n        service-name: snowy-biz-app\n        context-path: /\n      - name: SNOWY-PLUGIN-DEV\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-DEV\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-GEN\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-GEN\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-MOBILE\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-MOBILE\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-SYS\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-SYS\n        service-name: snowy-web-app\n        context-path: /', 'd64c91fa49d642f508e5200af551794e', '2024-04-24 14:34:18', '2026-10-12 23:22:38', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (4, 'snowy-xxl-job-app-dev.yaml', 'dev', '# 服务配置\nserver:\n  port: 9004\n  servlet:\n    context-path: /xxl-job-admin\n\n# spring相关配置\nspring:\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n        metadata:\n          management.context-path: ${server.servlet.context-path}/actuator\n      config:\n        server-addr: localhost:8848 #Nacos配置中心地址\n        file-extension: yml #指定yml格式的配置\n        username: nacos\n        password: nacos\n  datasource:\n    ### xxl-job, datasource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/snowy-cloud-job?autoReconnect=true&useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=CONVERT_TO_NULL&useSSL=false&nullCatalogMeansCurrent=true\n    username: root\n    password: 123456\n    ### datasource-pool\n    type: com.zaxxer.hikari.HikariDataSource\n    hikari:\n      minimum-idle: 10\n      maximum-pool-size: 30\n      auto-commit: true\n      idle-timeout: 30000\n      pool-name: HikariCP\n      max-lifetime: 900000\n      connection-timeout: 10000\n      connection-test-query: SELECT 1\n      validation-timeout: 1000\n  ### resources\n  resources:\n    static-locations: classpath:/static/\n  mvc:\n    servlet:\n      load-on-startup: 0\n    static-path-pattern: /static/**\n  ### freemarker\n  freemarker:\n    templateLoaderPath: classpath:/templates/\n    suffix: .ftl\n    charset: UTF-8\n    request-context-attribute: request\n    settings:\n      number_format: 0.##########\n  ### xxl-job, email\n  mail:\n    host: smtp.qq.com\n    port: 25\n    username: xxx@qq.com\n    from: xxx@qq.com\n    password: xxx\n    properties:\n      mail:\n        smtp:\n          auth: true\n          starttls:\n            enable: true\n            required: true\n          socketFactory:\n            class: javax.net.ssl.SSLSocketFactory\n\n### mybatis\nmybatis:\n  mapper-locations: classpath:/mybatis-mapper/*Mapper.xml\n# type-aliases-package: com.xxl.job.admin.core.model\n\n### xxl-job\n### xxl-job, access token\nxxl:\n  job:\n    accessToken: 123456\n    ### xxl-job, i18n (default is zh_CN, and you can choose \"zh_CN\", \"zh_TC\" and \"en\")\n    i18n: zh_CN\n    ## xxl-job, triggerpool max size\n    triggerpool:\n      fast:\n        max: 200\n      slow:\n        max: 100\n    ### xxl-job, log retention days\n    logretentiondays: 30\n\n### actuator\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n  health:\n    mail:\n      enabled: false', 'b19fe2120b77fcbc3a7c3c1ad66998c0', '2024-04-24 14:34:37', '2026-07-20 15:51:29', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5, 'snowy-web-app-dev.yaml', 'dev', '#########################################\n# server configuration\n#########################################\nserver:\n  port: 9101\n\n#########################################\n# spring profiles configuration\n#########################################\nspring:\n\n  #########################################\n  # multipart configuration\n  #########################################\n  servlet:\n    multipart:\n      max-request-size: 100MB\n      max-file-size: 100MB\n\n  #########################################\n  # mvc configuration\n  #########################################\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n\n  #########################################\n  # main configuration\n  #########################################\n  main:\n    allow-circular-references: true\n\n  #########################################\n  # boot configuration\n  #########################################\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n\n  #########################################\n  # cloud configuration\n  #########################################\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n  #########################################\n  # datasource configuration\n  #########################################\n\n  # mysql\n  datasource:\n    dynamic:\n      datasource:\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: jdbc:mysql://localhost:3306/snowy-cloud?useUnicode=true&characterEncoding=utf-8&useSSL=false&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true&useInformationSchema=true&rewriteBatchedStatements=true\n          username: root\n          password: 123456\n      strict: true\n\n      # oracle\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: oracle.jdbc.driver.OracleDriver\n      #          url: jdbc:oracle:thin:@//127.0.0.1:1521/XE?remarksReporting=true\n      #          username: SNOWY\n      #          password: 12345678\n      #      strict: true\n      #      druid:\n      #        validation-query: SELECT 1 FROM DUAL\n\n      # mssql\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.microsoft.sqlserver.jdbc.SQLServerDriver\n      #          url: jdbc:sqlserver://localhost:1433;DatabaseName=SNOWY\n      #          username: sa\n      #          password: 12345678\n      #      strict: true\n\n      # dm database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: dm.jdbc.driver.DmDriver\n      #          url: jdbc:dm://localhost:5236/SYSDBA\n      #          username: SYSDBA\n      #          password: SYSDBA\n      #      strict: true\n\n      # kingbase database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.kingbase8.Driver\n      #          url: jdbc:kingbase8://localhost:54321/snowy\n      #          username: SYSTEM\n      #          password: 123456\n      #      strict: true\n\n      # druid global configuration\n      public-key: MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAMWiTVtdXFVrgFHDDKELZM0SywkWY3KjugN90eY5Sogon1j8Y0ClPF7nx3FuE7pAeBKiv7ChIS0vvx/59WUpKmUCAwEAAQ==\n      druid:\n        initial-size: 10\n        max-active: 80\n        min-idle: 10\n        max-wait: 60000\n        pool-prepared-statements: true\n        max-pool-prepared-statement-per-connection-size: 20\n        validation-query-timeout: 2\n        test-on-borrow: false\n        test-on-return: false\n        test-while-idle: true\n        time-between-eviction-runs-millis: 60000\n        min-evictable-idle-time-millis: 300000\n        keep-alive: true\n        filters: stat\n        break-after-acquire-failure: false\n\n    # druid monitor configuration\n    druid:\n      stat-view-servlet:\n        enabled: false\n        login-username: snowyAdmin\n        login-password: Snowy@2026!\n        allow: \"\"\n\n  #########################################\n  # jackson configuration\n  #########################################\n  jackson:\n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    locale: zh_CN\n\n  #########################################\n  # redis configuration\n  #########################################\n  data:\n    redis:\n      database: 1\n      host: 127.0.0.1\n      port: 6379\n      password:\n      timeout: 10s\n\n#########################################\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\n#########################################\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n#########################################\n# mybatis-plus configuration\n#########################################\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    enable-sql-runner: true\n    db-config:\n      id-type: ASSIGN_ID\n      logic-delete-field: DELETE_FLAG\n      logic-delete-value: DELETED\n      logic-not-delete-value: NOT_DELETE\n  mapper-locations: classpath*:vip/xiaonuo/**/mapping/*.xml,com/bstek/**/mapping/*.xml\n  type-handlers-package: vip.xiaonuo.common.handler\n\n#########################################\n# easy-trans configuration\n#########################################\neasy-trans:\n  is-enable-redis: true\n  is-enable-global: true\n  is-enable-tile: true\n  is-enable-cloud: false\n\n#########################################\n# sa-token configuration\n#########################################\nsa-token:\n  token-name: token\n  timeout: 2592000\n  active-timeout: -1\n  is-concurrent: true\n  is-share: false\n  max-login-count: -1\n  token-style: random-32\n  is-log: false\n  is-print: false\n\n  # sa-token alone-redis configuration\n  alone-redis:\n    database: ${spring.data.redis.database}\n    host: ${spring.data.redis.host}\n    port: ${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    timeout: ${spring.data.redis.timeout}\n\n  # sso configuration\n  sso-client:\n    client:\n    auth-url:\n    signout-url:\n    push-url:\n    secret-key:\n\n#########################################\n# knife4j configuration\n#########################################\nknife4j:\n  enable: true\n  production: false\n  basic:\n    enable: false\n    username: snowyAdmin\n    password: Snowy@2026!\n  setting:\n    enableOpenApi: false\n    enableSwaggerModels: false\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Apache License 2.0 | Copyright 2022-[SNOWY](https://www.xiaonuo.vip)\n\n# knife4j doc groups\nspringdoc:\n  default-flat-param-object: true\n  group-configs:\n    - group: SNOWY-PLUGIN-AUTH\n      display-name: SNOWY-PLUGIN-AUTH\n      packages-to-scan: vip.xiaonuo.auth\n    - group: SNOWY-PLUGIN-DEV\n      display-name: SNOWY-PLUGIN-DEV\n      packages-to-scan: vip.xiaonuo.dev\n    - group: SNOWY-PLUGIN-GEN\n      display-name: SNOWY-PLUGIN-GEN\n      packages-to-scan: vip.xiaonuo.gen\n    - group: SNOWY-PLUGIN-MOBILE\n      display-name: SNOWY-PLUGIN-MOBILE\n      packages-to-scan: vip.xiaonuo.mobile\n    - group: SNOWY-PLUGIN-SYS\n      display-name: SNOWY-PLUGIN-SYS\n      packages-to-scan: vip.xiaonuo.sys\n\n\n#########################################\n# snowy configuration\n#########################################\nsnowy:\n  config:\n    # common configuration\n    common:\n      backend-url: http://localhost:9101\n      file-url: http://localhost:9003/api/webapp\n  # third-auth configuration iframe login\n  third-auth:\n    enabled: false\n    default-provider: default\n    providers:\n      default:\n        user-info-url:\n      # other:\n      #   user-info-url:\n\n# plugin dev-sms configuration\nsms-oa:\n  config-type: yaml\n  core-pool-size: 20\n  queue-capacity: 20\n  max-pool-size: 20', 'db4140c9849e93845a517092b83c12cc', '2024-04-24 14:35:03', '2026-10-12 23:22:38', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6, 'snowy-biz-app-dev.yaml', 'dev', '#########################################\n# server configuration\n#########################################\nserver:\n  port: 9102\n\n#########################################\n# spring profiles configuration\n#########################################\nspring:\n\n  #########################################\n  # multipart configuration\n  #########################################\n  servlet:\n    multipart:\n      max-request-size: 100MB\n      max-file-size: 100MB\n\n  #########################################\n  # mvc configuration\n  #########################################\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n\n  #########################################\n  # main configuration\n  #########################################\n  main:\n    allow-circular-references: true\n\n  #########################################\n  # boot configuration\n  #########################################\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n\n  #########################################\n  # cloud configuration\n  #########################################\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n  #########################################\n  # datasource configuration\n  #########################################\n\n  # mysql\n  datasource:\n    dynamic:\n      datasource:\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: jdbc:mysql://localhost:3306/snowy-cloud?useUnicode=true&characterEncoding=utf-8&useSSL=false&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true&useInformationSchema=true&rewriteBatchedStatements=true\n          username: root\n          password: 123456\n      strict: true\n\n      # oracle\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: oracle.jdbc.driver.OracleDriver\n      #          url: jdbc:oracle:thin:@//127.0.0.1:1521/XE?remarksReporting=true\n      #          username: SNOWY\n      #          password: 12345678\n      #      strict: true\n      #      druid:\n      #        validation-query: SELECT 1 FROM DUAL\n\n      # mssql\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.microsoft.sqlserver.jdbc.SQLServerDriver\n      #          url: jdbc:sqlserver://localhost:1433;DatabaseName=SNOWY\n      #          username: sa\n      #          password: 12345678\n      #      strict: true\n\n      # dm database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: dm.jdbc.driver.DmDriver\n      #          url: jdbc:dm://localhost:5236/SYSDBA\n      #          username: SYSDBA\n      #          password: SYSDBA\n      #      strict: true\n\n      # kingbase database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.kingbase8.Driver\n      #          url: jdbc:kingbase8://localhost:54321/snowy\n      #          username: SYSTEM\n      #          password: 123456\n      #      strict: true\n\n      # druid global configuration\n      public-key: MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAMWiTVtdXFVrgFHDDKELZM0SywkWY3KjugN90eY5Sogon1j8Y0ClPF7nx3FuE7pAeBKiv7ChIS0vvx/59WUpKmUCAwEAAQ==\n      druid:\n        initial-size: 10\n        max-active: 80\n        min-idle: 10\n        max-wait: 60000\n        pool-prepared-statements: true\n        max-pool-prepared-statement-per-connection-size: 20\n        validation-query-timeout: 2\n        test-on-borrow: false\n        test-on-return: false\n        test-while-idle: true\n        time-between-eviction-runs-millis: 60000\n        min-evictable-idle-time-millis: 300000\n        keep-alive: true\n        filters: stat\n        break-after-acquire-failure: false\n\n    # druid monitor configuration\n    druid:\n      stat-view-servlet:\n        enabled: false\n        login-username: snowyAdmin\n        login-password: Snowy@2026!\n\n  #########################################\n  # jackson configuration\n  #########################################\n  jackson:\n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    locale: zh_CN\n\n  #########################################\n  # redis configuration\n  #########################################\n  data:\n    redis:\n      database: 1\n      host: 127.0.0.1\n      port: 6379\n      password:\n      timeout: 10s\n\n#########################################\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\n#########################################\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n#########################################\n# mybatis-plus configuration\n#########################################\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    enable-sql-runner: true\n    db-config:\n      id-type: ASSIGN_ID\n      logic-delete-field: DELETE_FLAG\n      logic-delete-value: DELETED\n      logic-not-delete-value: NOT_DELETE\n  mapper-locations: classpath*:vip/xiaonuo/**/mapping/*.xml,com/bstek/**/mapping/*.xml\n  type-handlers-package: vip.xiaonuo.common.handler\n\n#########################################\n# easy-trans configuration\n#########################################\neasy-trans:\n  is-enable-redis: true\n  is-enable-global: true\n  is-enable-tile: true\n  is-enable-cloud: true\n\n#########################################\n# sa-token configuration\n#########################################\nsa-token:\n  token-name: token\n  timeout: 2592000\n  active-timeout: -1\n  is-concurrent: true\n  is-share: false\n  max-login-count: -1\n  token-style: random-32\n  is-log: false\n  is-print: false\n\n  # sa-token alone-redis configuration\n  alone-redis:\n    database: ${spring.data.redis.database}\n    host: ${spring.data.redis.host}\n    port: ${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    timeout: ${spring.data.redis.timeout}\n\n  # sso configuration\n  sso-client:\n    client:\n    auth-url:\n    signout-url:\n    push-url:\n    secret-key:\n\n#########################################\n# knife4j configuration\n#########################################\nknife4j:\n  enable: true\n  production: false\n  basic:\n    enable: false\n    username: snowyAdmin\n    password: Snowy@2026!\n  setting:\n    enableOpenApi: false\n    enableSwaggerModels: false\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Apache License 2.0 | Copyright 2022-[SNOWY](https://www.xiaonuo.vip)\n\n# knife4j doc groups\nspringdoc:\n  default-flat-param-object: true\n  group-configs:\n    - group: SNOWY-PLUGIN-BIZ\n      display-name: SNOWY-PLUGIN-BIZ\n      packages-to-scan: vip.xiaonuo.biz\n    - group: SNOWY-PLUGIN-CLIENT\n      display-name: SNOWY-PLUGIN-CLIENT\n      packages-to-scan: vip.xiaonuo.client\n\n#########################################\n# snowy configuration\n#########################################\nsnowy:\n  config:\n    # common configuration\n    common:\n      front-url: http://localhost:9000\n      backend-url: http://localhost:9102', 'ef37cb02c690fa86def8c50901a8c232', '2024-04-24 14:35:18', '2026-10-12 23:22:38', NULL, '192.168.0.114', '', 'snowy-cloud-dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7, 'snowy-actuator-app-test.yaml', 'test', '# 服务配置\nserver:\n  port: 9001\n\n# spring相关配置\nspring:\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"', 'c9ede45bff4951a66e71be96c176b17b', '2024-04-24 14:36:35', '2026-10-12 23:22:38', 'nacos', '192.168.0.105', '', 'snowy-cloud-test', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8, 'snowy-sentinel-app-test.yaml', 'test', '# 服务配置\nserver:\n  port: 9002\n  servlet:\n    #spring settings\n    encoding:\n      force: true\n      charset: UTF-8\n      enabled: true\n    #cookie name setting\n    session:\n      cookie:\n        name:\n          sentinel_dashboard_cookie: sentinel_dashboard_cookie\n\n# spring相关配置\nspring:\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n# logging settings\nlogging:\n  level:\n    org:\n      springframework:\n        web: INFO\n  file:\n    name: ${user.home}/logs/csp/sentinel-dashboard.log\n  pattern:\n    file: \'%d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\'\n    console: \'%d{yyyy-MM-dd HH:mm:ss} [%thread] %-5level %logger{36} - %msg%n\'\n\n# auth settings\nauth:\n  filter:\n    exclude-urls: /,/auth/login,/auth/logout,/registry/machine,/version,/actuator/**,/details\n    exclude-url-suffixes: htm,html,js,css,map,ico,ttf,woff,png\n  # If auth.enabled=false, Sentinel console disable login\n  username: sentinel\n  password: sentinel\n\n# Inject the dashboard version. It\'s required to enable\n# filtering in pom.xml for this resource file.\nsentinel:\n  dashboard:\n    version: 1.8.7', 'de07d06fe46cc30bd86b4c276e20b12c', '2024-04-24 14:36:57', '2026-10-12 23:22:38', 'nacos', '192.168.0.105', '', 'snowy-cloud-test', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (9, 'snowy-gateway-app-test.yaml', 'test', '# 服务配置\nserver:\n  port: 9003\n\n# spring相关配置\nspring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/snowy-cloud?useUnicode=true&characterEncoding=utf-8&useSSL=false&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true&useInformationSchema=true&rewriteBatchedStatements=true\n    username: root\n    password: 123456\n\n  # Oracle数据库\n  #spring:\n  #  datasource:\n  #    driver-class-name: oracle.jdbc.OracleDriver\n  #    url: jdbc:oracle:thin:@localhost:1521:xe\n  #    username: SNOWY-CLOUD-ORACLE\n  #    password: 123456\n\n  # SQLServer配置\n  #spring:\n  #  datasource:\n  #    driverClassName: com.microsoft.sqlserver.jdbc.SQLServerDriver\n  #    url: jdbc:sqlserver://localhost:1433;DatabaseName=snowy-cloud-mssql\n  #    username: sa\n  #    password: 123456\n\n  # PostgreSQL配置\n  #spring:\n  #  datasource:\n  #    driverClassName: org.postgresql.Driver\n  #    url: jdbc:postgresql://127.0.0.1:5432/snowy-cloud-postgresql\n  #    username: postgres\n  #    password: 123456\n\n  # 达梦数据库配置\n  #spring:\n  #  datasource:\n  #    driver-class-name: dm.jdbc.driver.DmDriver\n  #    url: jdbc:dm://localhost:5236/SYSDBA\n  #    username: SYSDBA\n  #    password: 123456789\n\n  # 人大金仓数据库\n  #spring:\n  #  datasource:\n  #    driver-class-name: com.kingbase8.Driver\n  #    url: jdbc:kingbase8://localhost:54321/snowy-cloud-kingbase\n  #    username: system\n  #    password: 123456\n  # #人大金仓数据库兼容问题，不需要加在sql语句中加public的解决方法：\n  # #在根目录data下的kingbase.conf文档里面找到search_path = \'\"$user\",PUBLIC,sys_catalog\'进行替换放开\n  # #重启数据库即可完全兼容，注意 sql中不能出现mysql中的关键字的单引号\n\n  # redis相关配置\n  data:\n    redis:\n      database: 1\n      host: 127.0.0.1\n      port: 6379\n      password:\n      timeout: 10s\n\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n    sentinel:\n      transport:\n        dashboard: localhost:9002\n        port: 8719\n      scg:\n        fallback:\n          mode: response\n          response-status: 455\n          response-body: error!\n    # gateway配置\n    gateway:\n      default-filters:\n        - DedupeResponseHeader=Access-Control-Allow-Origin\n      globalcors:\n        add-to-simple-url-handler-mapping: true\n        corsConfigurations:\n          \'[/**]\':\n            allowed-origins-patterns: \"*\"\n            allowed-methods: \"*\"\n            allowed-headers: \"*\"\n            allow-credentials: true\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        - id: snowy-web-app\n          uri: lb://snowy-web-app\n          predicates:\n            - Path=/api/webapp/**\n          filters:\n            - SwaggerHeaderFilter\n            - StripPrefix=2 #去掉Path中前两个节点\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n        - id: snowy-web-app\n          uri: lb://snowy-web-app\n          predicates:\n            - Path=/druid/**\n          filters:\n            - SwaggerHeaderFilter\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n        - id: snowy-biz-app\n          uri: lb://snowy-biz-app\n          predicates:\n            - Path=/api/bizapp/**\n          filters:\n            - SwaggerHeaderFilter\n            - StripPrefix=2 #去掉Path中前两个节点\n            - name: Retry\n              args:\n                retries: 1 #重试次数\n\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n#########################################\n# sa-token configuration\n#########################################\nsa-token:\n  token-name: token\n  timeout: 2592000\n  active-timeout: -1\n  is-concurrent: true\n  is-share: false\n  max-login-count: -1\n  token-style: random-32\n  is-log: false\n  is-print: false\n\n  # sa-token alone-redis configuration\n  alone-redis:\n    database: ${spring.data.redis.database}\n    host: ${spring.data.redis.host}\n    port: ${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    timeout: ${spring.data.redis.timeout}\n\n  # sso configuration\n  sso-client:\n    client:\n    auth-url:\n    signout-url:\n    push-url:\n    secret-key:\n\n# knife4j 文档聚合\nknife4j:\n  enable: true\n  production: false\n  basic:\n    enable: true\n    username: snowyAdmin\n    password: Snowy@2026!\n  setting:\n    enableOpenApi: false\n    enableSwaggerModels: false\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Apache License 2.0 | Copyright 2022-[SNOWY](https://www.xiaonuo.vip)\n  # gateway聚合swagger文档\n  gateway:\n    enabled: true\n    # 排序规则(tag/operation排序自4.2.0版本新增)\n    # 取值：alpha-默认排序规则，官方swagger-ui默认实现,order-Knife4j提供的增强排序规则，开发者可扩展x-order，根据数值来自定义排序\n    tags-sorter: order\n    operations-sorter: order\n    # 指定手动配置的模式(默认为该模式)\n    strategy: manual\n    routes:\n      - name: SNOWY-PLUGIN-AUTH\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-AUTH\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-BIZ\n        url: /api/bizapp/v3/api-docs/SNOWY-PLUGIN-BIZ\n        service-name: snowy-biz-app\n        context-path: /\n      - name: SNOWY-PLUGIN-CLIENT\n        url: /api/bizapp/v3/api-docs/SNOWY-PLUGIN-CLIENT\n        service-name: snowy-biz-app\n        context-path: /\n      - name: SNOWY-PLUGIN-DEV\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-DEV\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-GEN\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-GEN\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-MOBILE\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-MOBILE\n        service-name: snowy-web-app\n        context-path: /\n      - name: SNOWY-PLUGIN-SYS\n        url: /api/webapp/v3/api-docs/SNOWY-PLUGIN-SYS\n        service-name: snowy-web-app\n        context-path: /', 'd64c91fa49d642f508e5200af551794e', '2024-04-24 14:37:20', '2026-10-12 23:22:38', NULL, '192.168.0.105', '', 'snowy-cloud-test', '', '', '', 'yaml', '', '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (10, 'snowy-xxl-job-app-test.yaml', 'test', '# 服务配置\nserver:\n  port: 9004\n  servlet:\n    context-path: /xxl-job-admin\n\n# spring相关配置\nspring:\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    # nacos配置\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n        metadata:\n          management.context-path: ${server.servlet.context-path}/actuator\n      config:\n        server-addr: localhost:8848 #Nacos配置中心地址\n        file-extension: yml #指定yml格式的配置\n        username: nacos\n        password: nacos\n  datasource:\n    ### xxl-job, datasource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/snowy-cloud-job?autoReconnect=true&useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=CONVERT_TO_NULL&useSSL=false&nullCatalogMeansCurrent=true\n    username: root\n    password: 123456\n    ### datasource-pool\n    type: com.zaxxer.hikari.HikariDataSource\n    hikari:\n      minimum-idle: 10\n      maximum-pool-size: 30\n      auto-commit: true\n      idle-timeout: 30000\n      pool-name: HikariCP\n      max-lifetime: 900000\n      connection-timeout: 10000\n      connection-test-query: SELECT 1\n      validation-timeout: 1000\n  ### resources\n  resources:\n    static-locations: classpath:/static/\n  mvc:\n    servlet:\n      load-on-startup: 0\n    static-path-pattern: /static/**\n  ### freemarker\n  freemarker:\n    templateLoaderPath: classpath:/templates/\n    suffix: .ftl\n    charset: UTF-8\n    request-context-attribute: request\n    settings:\n      number_format: 0.##########\n  ### xxl-job, email\n  mail:\n    host: smtp.qq.com\n    port: 25\n    username: xxx@qq.com\n    from: xxx@qq.com\n    password: xxx\n    properties:\n      mail:\n        smtp:\n          auth: true\n          starttls:\n            enable: true\n            required: true\n          socketFactory:\n            class: javax.net.ssl.SSLSocketFactory\n\n### mybatis\nmybatis:\n  mapper-locations: classpath:/mybatis-mapper/*Mapper.xml\n# type-aliases-package: com.xxl.job.admin.core.model\n\n### xxl-job\n### xxl-job, access token\nxxl:\n  job:\n    accessToken: 123456\n    ### xxl-job, i18n (default is zh_CN, and you can choose \"zh_CN\", \"zh_TC\" and \"en\")\n    i18n: zh_CN\n    ## xxl-job, triggerpool max size\n    triggerpool:\n      fast:\n        max: 200\n      slow:\n        max: 100\n    ### xxl-job, log retention days\n    logretentiondays: 30\n\n### actuator\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n  health:\n    mail:\n      enabled: false', 'b19fe2120b77fcbc3a7c3c1ad66998c0', '2024-04-24 14:37:43', '2026-10-12 23:22:38', 'nacos', '192.168.0.105', '', 'snowy-cloud-test', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info`(`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (11, 'snowy-web-app-test.yaml', 'test', '#########################################\n# server configuration\n#########################################\nserver:\n  port: 9101\n\n#########################################\n# spring profiles configuration\n#########################################\nspring:\n\n  #########################################\n  # multipart configuration\n  #########################################\n  servlet:\n    multipart:\n      max-request-size: 100MB\n      max-file-size: 100MB\n\n  #########################################\n  # mvc configuration\n  #########################################\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n\n  #########################################\n  # main configuration\n  #########################################\n  main:\n    allow-circular-references: true\n\n  #########################################\n  # boot configuration\n  #########################################\n  boot:\n    admin:\n      client:\n        url: http://localhost:9001\n        instance:\n          # 默认使用的是主机名注册，改为使用ip注册\n          service-host-type: ip\n\n  #########################################\n  # cloud configuration\n  #########################################\n  cloud:\n    loadbalancer:\n      ribbon:\n        enabled: false\n      cache:\n        enabled: true\n        caffeine:\n          spec: initialCapacity=500,expireAfterWrite=5s\n    nacos:\n      discovery:\n        server-addr: ${spring.cloud.nacos.config.server-addr}\n        namespace: ${spring.cloud.nacos.config.namespace}\n        group: ${spring.cloud.nacos.config.group}\n        username: ${spring.cloud.nacos.config.username}\n        password: ${spring.cloud.nacos.config.password}\n\n  #########################################\n  # datasource configuration\n  #########################################\n\n  # mysql\n  datasource:\n    dynamic:\n      datasource:\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: jdbc:mysql://localhost:3306/snowy-cloud?useUnicode=true&characterEncoding=utf-8&useSSL=false&allowPublicKeyRetrieval=true&nullCatalogMeansCurrent=true&useInformationSchema=true&rewriteBatchedStatements=true\n          username: root\n          password: 123456\n      strict: true\n\n      # oracle\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: oracle.jdbc.driver.OracleDriver\n      #          url: jdbc:oracle:thin:@//127.0.0.1:1521/XE?remarksReporting=true\n      #          username: SNOWY\n      #          password: 12345678\n      #      strict: true\n      #      druid:\n      #        validation-query: SELECT 1 FROM DUAL\n\n      # mssql\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.microsoft.sqlserver.jdbc.SQLServerDriver\n      #          url: jdbc:sqlserver://localhost:1433;DatabaseName=SNOWY\n      #          username: sa\n      #          password: 12345678\n      #      strict: true\n\n      # dm database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: dm.jdbc.driver.DmDriver\n      #          url: jdbc:dm://localhost:5236/SYSDBA\n      #          username: SYSDBA\n      #          password: SYSDBA\n      #      strict: true\n\n      # kingbase database\n      #  datasource:\n      #    dynamic:\n      #      datasource:\n      #        master:\n      #          driver-class-name: com.kingbase8.Driver\n      #          url: jdbc:kingbase8://localhost:54321/snowy\n      #          username: SYSTEM\n      #          password: 123456\n      #      strict: true\n\n      # druid global configuration\n      public-key: MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAMWiTVtdXFVrgFHDDKELZM0SywkWY3KjugN90eY5Sogon1j8Y0ClPF7nx3FuE7pAeBKiv7ChIS0vvx/59WUpKmUCAwEAAQ==\n      druid:\n        initial-size: 10\n        max-active: 80\n        min-idle: 10\n        max-wait: 60000\n        pool-prepared-statements: true\n        max-pool-prepared-statement-per-connection-size: 20\n        validation-query-timeout: 2\n        test-on-borrow: false\n        test-on-return: false\n        test-while-idle: true\n        time-between-eviction-runs-millis: 60000\n        min-evictable-idle-time-millis: 300000\n        keep-alive: true\n        filters: stat\n        break-after-acquire-failure: false\n\n    # druid monitor configuration\n    druid:\n      stat-view-servlet:\n        enabled: false\n        login-username: snowyAdmin\n        login-password: Snowy@2026!\n        allow: \"\"\n\n  #########################################\n  # jackson configuration\n  #########################################\n  jackson:\n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    locale: zh_CN\n\n  #########################################\n  # redis configuration\n  #########################################\n  data:\n    redis:\n      database: 1\n      host: 127.0.0.1\n      port: 6379\n      password:\n      timeout: 10s\n\n#########################################\n# 开放所有endpoint，实际生产根据自身需要开放，出于安全考虑不建议全部开放\n#########################################\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \"*\"\n    health:\n      show-details: \"ALWAYS\"\n\n#########################################\n# mybatis-plus configuration\n#########################################\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config:\n    banner: false\n    enable-sql-runner: true\n    db-config:\n      id-type: ASSIGN_ID\n      logic-delete-field: DELETE_FLAG\n      logic-delete-value: DELETED\n      logic-not-delete-value: NOT_DELETE\n  mapper-locations: classpath*:vip/xiaonuo/**/mapping/*.xml,com/bstek/**/mapping/*.xml\n  type-handlers-package: vip.xiaonuo.common.handler\n\n#########################################\n# easy-trans configuration\n#########################################\neasy-trans:\n  is-enable-redis: true\n  is-enable-global: true\n  is-enable-tile: true\n  is-enable-cloud: false\n\n#########################################\n# sa-token configuration\n#########################################\nsa-token:\n  token-name: token\n  timeout: 2592000\n  active-timeout: -1\n  is-concurrent: true\n  is-share: false\n  max-login-count: -1\n  token-style: random-32\n  is-log: false\n  is-print: false\n\n  # sa-token alone-redis configuration\n  alone-redis:\n    database: ${spring.data.redis.database}\n    host: ${spring.data.redis.host}\n    port: ${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    timeout: ${spring.data.redis.timeout}\n\n  # sso configuration\n  sso-client:\n    client:\n    auth-url:\n    signout-url:\n    push-url:\n    secret-key:\n\n#########################################\n# knife4j configuration\n#########################################\nknife4j:\n  enable: true\n  production: false\n  basic:\n    enable: false\n    username: snowyAdmin\n    password: Snowy@2026!\n  setting:\n    enableOpenApi: false\n    enableSwaggerModels: false\n    enableFooter: false\n    enableFooterCustom: true\n    footerCustomContent: Apache License 2.0 | Copyright 2022-[SNOWY](https://www.xiaonuo.vip)\n\n# knife4j doc groups\nspringdoc:\n  default-flat-param-object: true\n  group-configs:\n    - group: SNOWY-PLUGIN-AUTH\n      display-name: SNOWY-PLUGIN-AUTH\n      packages-to-scan: vip.xiaonuo.auth\n    - group: SNOWY-PLUGIN-DEV\n      display-name: SNOWY-PLUGIN-DEV\n      packages-to-scan: vip.xiaonuo.dev\n    - group: SNOWY-PLUGIN-GEN\n      display-name: SNOWY-PLUGIN-GEN\n      packages-to-scan: vip.xiaonuo.gen\n    - group: SNOWY-PLUGIN-MOBILE\n      display-name: SNOWY-PLUGIN-MOBILE\n      packages-to-scan: vip.xiaonuo.mobile\n    - group: SNOWY-PLUGIN-SYS\n      display-name: SNOWY-PLUGIN-SYS\n      packages-to-scan: vip.xiaonuo.sys\n\n\n#########################################\n# snowy configuration\n#########################################\nsnowy:\n  config:\n    # common configuration\n    common:\n      backend-url: http://localhost:9101\n      file-url: http://localhost:9003/api/webapp\n  # third-auth configuration iframe login\n  third-auth:\n    enabled: false\n    default-provider: default\n    providers:\n      default:\n        user-info-url:\n      # other:\n      #   user-info-url:\n\n# plugin dev-sms configuration\nsms-oa:\n  config-type: yaml\n  core-pool-size: 20\n  queue-capacity: 20\n  max-pool-size: 20', 'db4140c9849e93845a517092b83c12cc', '2024-04-24 14:38:06', '2026-10-12 23:22:38', NULL, '192.168.0.105', '', 'snowy-cloud-test', '', '', '', 'yaml', '', '');
