mon configuration\n    common:\n      front-url: http://localhost:9000\n      backend-url: http://localhost:9102', 'ef37cb02c690fa86def8c50901a8c232', '2024-04-24 17:34:31', '2026-10-12 23:22:38', NULL, '192.168.0.105', '', 'snowy-cloud-prod', '', '', '', 'yaml', '', '');
